# DP implementation based on the specified template
# DP[i][v][u]: Count of valid partial assignments up to iteration i, where v is the state of element i, and u is the state of element i+21.

N = 21
# Initialize DP table: (N+1) iterations, 2 states for v, 2 states for u
# DP[i][v][u]
dp = [[[0] * 2 for _ in range(2)] for _ in range(N + 1)]

# Base Case: i = 1
# Constraints: v_1 + u_1 <= 1
for v1 in range(2):
    for u1 in range(2):
        if v1 + u1 <= 1:
            dp[1][v1][u1] = 1

# Iteration: i = 2 to N (21)
for i in range(2, N + 1):
    # Iterate over all possible previous states (v_{i-1}, u_{i-1})
    for v_prev in range(2):
        for u_prev in range(2):
            if dp[i-1][v_prev][u_prev] == 0:
                continue

            count_prev = dp[i-1][v_prev][u_prev]

            # Iterate over all current states (v_i, u_i)
            for v_curr in range(2):
                for u_curr in range(2):
                    # Apply the transition constraints:
                    # 1. v_{i-1} + v_i <= 1 (Constraint on sequence i)
                    C1 = (v_prev + v_curr <= 1)
                    # 2. u_{i-1} + u_i <= 1 (Constraint on sequence i+21)
                    C2 = (u_prev + u_curr <= 1)
                    # 3. v_i + u_i <= 1 (Constraint between i and i+21)
                    C3 = (v_curr + u_curr <= 1)

                    if C1 and C2 and C3:
                        dp[i][v_curr][u_curr] += count_prev

# Final calculation: Sum up all counts at i=21
final_count = 0
for v_final in range(2):
    for u_final in range(2):
        final_count += dp[N][v_final][u_final]

print(f"The final count is: {final_count}")

