        return True
    subset_list = sorted(list(subset))
    for i in range(len(subset_list)):
        for j in range(i + 1, len(subset_list)):
            x = subset_list[i]
            y = subset_list[j]
            diff = abs(x - y)
            if diff == 1 or diff == D:
                return False
    return True

